-- Kathmandu Momo menu seed
-- 1) Upload deploy/menu-pack/menu/* to /home/thehairc/kathmandu-momo/menu/
-- 2) Run this SQL in phpPgAdmin (Postgres)
-- Safe to re-run: clears existing menu categories/items first.

BEGIN;

DELETE FROM menu_item_variants;
DELETE FROM menu_items;
DELETE FROM menu_categories;

-- Reset sequences
ALTER SEQUENCE menu_categories_id_seq RESTART WITH 1;
ALTER SEQUENCE menu_items_id_seq RESTART WITH 1;



COMMIT;

-- Verify: SELECT c.name, COUNT(i.id) FROM menu_categories c LEFT JOIN menu_items i ON i.category_id = c.id GROUP BY c.name ORDER BY MIN(c.display_order);
